61	    /// Creates a new `Writer` with user defined capacity.
62	    ///
63	    /// All output from the given operation will be forwarded to `writer`.
64	    pub fn new_with_capacity(
65	        writer: W,
66	        operation: D,
67	        capacity: usize,
68	    ) -> Self {
69	        Self::with_output_buffer(
70	            Vec::with_capacity(capacity),
71	            writer,
72	            operation,
73	        )
74	    }
