77	    ///
78	    /// The output buffer _must_ have pre-allocated capacity (its capacity will not be changed after).
79	    ///
80	    /// Usually you would use `Vec::with_capacity(desired_buffer_size)`.
81	    pub fn with_output_buffer(
82	        output_buffer: Vec<u8>,
83	        writer: W,
84	        operation: D,
85	    ) -> Self {
86	        Writer {
87	            writer,
88	            operation,
89	
90	            offset: 0,
91	            // 32KB buffer? That's what flate2 uses
92	            buffer: output_buffer,
93	
94	            finished: false,
95	            finish_requested: false,
96	            finished_frame: false,
97	        }
98	    }
