126	    /// Runs a single step of the finish operation.
127	    ///
128	    /// Generates the next batch of frame trailer into `self.buffer`,
129	    /// and updates `self.finished` accordingly.
130	    fn finish_step(&mut self) -> io::Result<()> {
131	        let finished_frame = self.finished_frame;
132	        let hint = self.with_buffer(|dst, op| op.finish(dst, finished_frame));
133	        self.offset = 0;
134	        // println!("Hint: {:?}\nOut:{:?}", hint, &self.buffer);
135	
136	        // We return here if zstd had a problem.
137	        // Could happen with invalid data, ...
138	        let hint = hint?;
139	
140	        if hint != 0 && self.buffer.is_empty() {
141	            // This happens if we are decoding an incomplete frame.
142	            return Err(io::Error::new(
143	                io::ErrorKind::UnexpectedEof,
144	                "incomplete frame",
145	            ));
146	        }
147	
148	        // println!("Finishing {}, {}", bytes_written, hint);
149	
150	        self.finished = hint == 0;
151	        Ok(())
152	    }
153	
154	    /// Run the given closure on `self.buffer`.
155	    ///
156	    /// The buffer will be cleared, and made available wrapped in an `OutBuffer`.
157	    fn with_buffer<F, T>(&mut self, f: F) -> T
158	    where
159	        F: FnOnce(&mut OutBuffer<'_, Vec<u8>>, &mut D) -> T,
160	    {
161	        self.buffer.clear();
162	        let mut output = OutBuffer::around(&mut self.buffer);
163	        // eprintln!("Output: {:?}", output);
164	        f(&mut output, &mut self.operation)
165	    }
166	
167	    /// Attempt to write `self.buffer` to the wrapped writer.
168	    ///
169	    /// Returns `Ok(())` once all the buffer has been written.
170	    fn write_from_offset(&mut self) -> io::Result<()> {
171	        // The code looks a lot like `write_all`, but keeps track of what has
172	        // been written in case we're interrupted.
173	        while self.offset < self.buffer.len() {
174	            match self.writer.write(&self.buffer[self.offset..]) {
