231	where
232	    W: Write,
233	    D: Operation,
234	{
235	    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
236	        if self.finished {
237	            return Err(io::Error::new(
238	                io::ErrorKind::Other,
239	                "encoder is finished",
240	            ));
241	        }
242	        // Keep trying until _something_ has been consumed.
243	        // As soon as some input has been taken, we cannot afford
244	        // to take any chance: if an error occurs, the user couldn't know
245	        // that some data _was_ successfully written.
246	        loop {
247	            // First, write any pending data from `self.buffer`.
248	            self.write_from_offset()?;
249	            // At this point `self.buffer` can safely be discarded.
250	
251	            // Support writing concatenated frames by re-initializing the
252	            // context.
253	            if self.finished_frame {
254	                self.operation.reinit()?;
255	                self.finished_frame = false;
256	            }
257	
258	            let mut src = InBuffer::around(buf);
259	            let hint = self.with_buffer(|dst, op| op.run(&mut src, dst));
260	            let bytes_read = src.pos;
261	
262	            // eprintln!(
263	            //     "Write Hint: {:?}\n src: {:?}\n dst: {:?}",
264	            //     hint, src, self.buffer
265	            // );
266	
267	            self.offset = 0;
268	            let hint = hint?;
269	
270	            if hint == 0 {
271	                self.finished_frame = true;
272	            }
273	
274	            // As we said, as soon as we've consumed something, return.
275	            if bytes_read > 0 || buf.is_empty() {
276	                // println!("Returning {}", bytes_read);
277	                return Ok(bytes_read);
278	            }
279	        }
280	    }
281	
282	    fn flush(&mut self) -> io::Result<()> {
283	        let mut flushed = self.finished;
284	        loop {
285	            // If the output is blocked or has an error, return now.
286	            self.write_from_offset()?;
287	
288	            if flushed {
289	                break;
290	            }
291	
292	            if self.finish_requested {
293	                // A finish was requested but did not complete (the writer
294	                // blocked halfway through the frame trailer, for instance).
295	                // Keep closing the frame instead of starting a regular
296	                // flush: the operation must not be taken back to a state
297	                // where new data could be compressed.
298	                self.finish_step()?;
299	                flushed = self.finished;
300	            } else {
301	                let hint = self.with_buffer(|dst, op| op.flush(dst));
302	
303	                self.offset = 0;
304	                let hint = hint?;
305	
306	                flushed = hint == 0;
307	            }
308	        }
309	
310	        self.writer.flush()
311	    }
312	}
