1	//! The write-side streaming encoder must survive an output that blocks
2	//! (`WouldBlock`) halfway through `finish()`: once the output recovers, the
3	//! caller may `flush()` and `finish()` in any order and must still end up
4	//! with exactly one complete, uncorrupted frame - no lost bytes, no
5	//! duplicated bytes, no extra empty frame.
6	
7	use std::io::{self, Write};
8	
9	use zstd::stream::raw;
10	use zstd::stream::write::Encoder;
11	use zstd::stream::{decode_all, encode_all, zio};
12	
13	const LEVEL: i32 = 3;
14	
15	/// Compressible but not trivial input.
16	fn input() -> Vec<u8> {
17	    (0..100_000).map(|i| (i % 251) as u8).collect()
18	}
19	
20	/// Deterministic incompressible input: the frame trailer zstd has to emit
21	/// on `finish()` is then much larger than the encoder's output buffer, so a
22	/// blocked writer interrupts the finish while batches of trailer are still
23	/// being generated.
24	fn noise(len: usize) -> Vec<u8> {
25	    let mut state = 0x9E3779B97F4A7C15u64;
26	    (0..len)
27	        .map(|_| {
28	            state ^= state << 13;
29	            state ^= state >> 7;
30	            state ^= state << 17;
31	            state as u8
32	        })
33	        .collect()
34	}
35	
36	fn reference(data: &[u8]) -> Vec<u8> {
37	    encode_all(data, LEVEL).unwrap()
38	}
39	
40	/// A writer that accepts at most `chunk` bytes per `write()` call, and only
41	/// while `budget` lasts; once the budget is exhausted it returns
42	/// `WouldBlock` until `unblock()` is called.
43	struct ThrottledWriter {
44	    data: Vec<u8>,
45	    chunk: usize,
46	    budget: usize,
47	    flush_blocked: bool,
48	}
49	
50	impl ThrottledWriter {
51	    fn new(chunk: usize) -> Self {
52	        ThrottledWriter {
53	            data: Vec::new(),
54	            chunk,
55	            budget: usize::MAX,
56	            flush_blocked: false,
57	        }
58	    }
59	
60	    /// Accept at most `n` more bytes (across all calls), then block.
61	    fn allow(&mut self, n: usize) {
62	        self.budget = n;
63	    }
64	
65	    fn unblock(&mut self) {
66	        self.budget = usize::MAX;
67	    }
68	}
69	
70	impl Write for ThrottledWriter {
71	    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
72	        if self.budget == 0 {
73	            return Err(io::Error::new(
74	                io::ErrorKind::WouldBlock,
75	                "output is blocked",
76	            ));
77	        }
78	        let n = self.chunk.min(buf.len()).min(self.budget);
79	        self.data.extend_from_slice(&buf[..n]);
80	        self.budget -= n;
81	        Ok(n)
82	    }
83	
84	    fn flush(&mut self) -> io::Result<()> {
85	        if self.flush_blocked {
86	            return Err(io::Error::new(
87	                io::ErrorKind::WouldBlock,
88	                "flush is blocked",
89	            ));
90	        }
91	        Ok(())
92	    }
93	}
94	
95	fn would_block(err: &io::Error) -> bool {
96	    err.kind() == io::ErrorKind::WouldBlock
97	}
98	
99	/// Keep writing until everything has been accepted, tolerating `WouldBlock`.
100	fn write_all_through_blocks<W: Write>(
101	    w: &mut W,
102	    mut buf: &[u8],
103	) -> io::Result<()> {
104	    while !buf.is_empty() {
105	        match w.write(buf) {
106	            Ok(0) => {
107	                return Err(io::Error::new(
108	                    io::ErrorKind::WriteZero,
109	                    "zero-length write",
110	                ))
111	            }
112	            Ok(n) => buf = &buf[n..],
113	            Err(ref e) if would_block(e) => {}
114	            Err(e) => return Err(e),
115	        }
116	    }
117	    Ok(())
118	}
119	
120	/// Keep flushing until it goes through, tolerating `WouldBlock`.
121	fn flush_through_blocks<W: Write>(w: &mut W) -> io::Result<()> {
122	    loop {
123	        match w.flush() {
124	            Ok(()) => return Ok(()),
125	            Err(ref e) if would_block(e) => {}
126	            Err(e) => return Err(e),
127	        }
128	    }
129	}
130	
131	/// Keep finishing until it goes through, tolerating `WouldBlock`.
132	fn finish_through_blocks<W: Write>(w: &mut Encoder<'_, W>) -> io::Result<()> {
133	    loop {
134	        match w.do_finish() {
135	            Ok(()) => return Ok(()),
136	            Err(ref e) if would_block(e) => {}
137	            Err(e) => return Err(e),
138	        }
139	    }
140	}
141	
142	/// A finish interrupted by `WouldBlock`, then a `flush()`, must complete the
143	/// very same frame; further `finish`/`flush` calls must not add any output.
144	#[test]
145	fn finish_blocked_then_flush_completes_the_same_frame() {
146	    let input = noise(300_000);
147	    let expected = reference(&input);
148	
149	    let mut encoder =
150	        Encoder::new(ThrottledWriter::new(usize::MAX), LEVEL).unwrap();
151	    encoder.write_all(&input).unwrap();
152	
153	    // Let the finish push a couple of bytes, then block it.
154	    encoder.get_mut().allow(2);
155	    let err = encoder.do_finish().unwrap_err();
156	    assert!(would_block(&err), "expected WouldBlock, got {:?}", err);
157	
158	    // The output recovers; a flush must drive the interrupted finish to
159	    // completion rather than corrupting or restarting anything.
160	    encoder.get_mut().unblock();
161	    encoder.flush().unwrap();
162	    assert_eq!(encoder.get_ref().data, expected);
163	
164	    // Finishing again must succeed without emitting anything more.
165	    encoder.do_finish().unwrap();
166	    assert_eq!(encoder.get_ref().data, expected);
167	
168	    // Neither must repeated flushes.
169	    encoder.flush().unwrap();
170	    encoder.flush().unwrap();
171	    assert_eq!(encoder.get_ref().data, expected);
172	
173	    // Writing past the finish is rejected.
174	    assert!(encoder.write(b"nope").is_err());
175	
176	    // And try_finish hands the writer back, still with no extra output.
177	    let writer = encoder.try_finish().map_err(|(_, e)| e).unwrap();
178	    assert_eq!(writer.data, expected);
179	    assert_eq!(decode_all(&writer.data[..]).unwrap(), input);
180	}
181	
182	/// `flush()` before any finish request keeps its usual meaning: push out
183	/// what has been accepted so far, then keep accepting more input.
184	#[test]
185	fn flush_before_finish_still_allows_more_writes() {
186	    let input = input();
187	    let (first, second) = input.split_at(input.len() / 2);
188	
189	    let mut encoder =
190	        Encoder::new(ThrottledWriter::new(usize::MAX), LEVEL).unwrap();
191	    encoder.write_all(first).unwrap();
192	    encoder.flush().unwrap();
193	    encoder.write_all(second).unwrap();
194	    let writer = encoder.finish().unwrap();
195	
196	    assert_eq!(decode_all(&writer.data[..]).unwrap(), input);
197	}
198	
199	/// With a one-byte output buffer and a one-byte-at-a-time writer, the frame
200	/// trailer is produced in many batches; blocking and alternating
201	/// flush/finish in the middle of it must still yield the exact same frame.
202	#[test]
203	fn tiny_buffer_finish_blocked_mid_trailer() {
204	    let input = input();
205	    let expected = reference(&input);
206	
207	    let writer = ThrottledWriter::new(1);
208	    let raw = raw::Encoder::new(LEVEL).unwrap();
209	    let zio_writer = zio::Writer::new_with_capacity(writer, raw, 1);
210	    let mut encoder = Encoder::with_writer(zio_writer);
211	
212	    write_all_through_blocks(&mut encoder, &input).unwrap();
213	
214	    // Block while the trailer is still being generated in batches.
215	    encoder.get_mut().allow(3);
216	    let err = encoder.do_finish().unwrap_err();
217	    assert!(would_block(&err), "expected WouldBlock, got {:?}", err);
218	
219	    // A flush with a small budget blocks again, partway through the trailer.
220	    encoder.get_mut().allow(2);
221	    let err = encoder.flush().unwrap_err();
222	    assert!(would_block(&err), "expected WouldBlock, got {:?}", err);
223	
224	    // Once unblocked, flush completes the close...
225	    encoder.get_mut().unblock();
226	    encoder.flush().unwrap();
227	    assert_eq!(encoder.get_ref().data, expected);
228	
229	    // ...and finishing afterwards adds nothing.
230	    encoder.do_finish().unwrap();
231	    assert_eq!(encoder.get_ref().data, expected);
232	
233	    let writer = encoder.finish().unwrap();
234	    assert_eq!(writer.data, expected);
235	    assert_eq!(decode_all(&writer.data[..]).unwrap(), input);
236	}
237	
238	/// An output that accepts a single byte at a time and blocks between every
239	/// two writes: errors come back promptly, and resuming never asks the caller
240	/// to re-submit already-accepted data.
241	#[test]
242	fn one_byte_writer_with_intermittent_wouldblock() {
243	    struct Stutter {
244	        data: Vec<u8>,
245	        accept_next: bool,
246	    }
247	
248	    impl Write for Stutter {
249	        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
250	            if self.accept_next && !buf.is_empty() {
251	                self.data.push(buf[0]);
252	                self.accept_next = false;
253	                Ok(1)
254	            } else {
255	                self.accept_next = true;
256	                Err(io::Error::new(io::ErrorKind::WouldBlock, "stutter"))
257	            }
258	        }
259	
260	        fn flush(&mut self) -> io::Result<()> {
261	            Ok(())
262	        }
263	    }
264	
265	    let input = input();
266	    let expected = reference(&input);
267	
268	    let mut encoder = Encoder::new(
269	        Stutter {
270	            data: Vec::new(),
271	            accept_next: true,
272	        },
273	        LEVEL,
274	    )
275	    .unwrap();
276	
277	    write_all_through_blocks(&mut encoder, &input).unwrap();
278	    // Alternate flush and finish attempts; each WouldBlock just means
279	    // "call me again".
280	    loop {
281	        match encoder.do_finish() {
282	            Ok(()) => break,
283	            Err(ref e) if would_block(e) => match encoder.flush() {
284	                Ok(()) | Err(_) => {}
285	            },
