    let err = decoder.do_finish().unwrap_err();
    assert_eq!(err.kind(), io::ErrorKind::UnexpectedEof);

    // An empty write does not change that.
    assert_eq!(decoder.write(&[]).unwrap(), 0);
    let err = decoder.do_finish().unwrap_err();
    assert_eq!(err.kind(), io::ErrorKind::UnexpectedEof);
}

