    let compressed = frame(b"");
    assert!(!compressed.is_empty(), "an empty frame is still a frame");

    let mut decoder = Decoder::new(Vec::new()).unwrap();
    decoder.write_all(&compressed).unwrap();
    let output = decoder.finish().unwrap();
    assert_eq!(output, b"");
}

